import{_ as e,o as t,c as s,a3 as i}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Enable LAN access (Ollama)","description":"Set OLLAMA_HOST=0.0.0.0 and firewall rules so phone MiniTavern can reach Ollama on your PC.","frontmatter":{"title":"Enable LAN access (Ollama)","description":"Set OLLAMA_HOST=0.0.0.0 and firewall rules so phone MiniTavern can reach Ollama on your PC.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Enable LAN access (Ollama) · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Set OLLAMA_HOST=0.0.0.0 and firewall rules so phone MiniTavern can reach Ollama on your PC."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/ollama/lan"}]]},"headers":[],"relativePath":"en/ollama/lan.md","filePath":"en/ollama/lan.md","lastUpdated":1787224147000}'),l={name:"en/ollama/lan.md"};function n(r,a,o,h,p,d){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="enable-lan-access-ollama" tabindex="-1">Enable LAN access (Ollama) <a class="header-anchor" href="#enable-lan-access-ollama" aria-label="Permalink to &quot;Enable LAN access (Ollama)&quot;">​</a></h1><p>By default Ollama often listens only on the PC. For the phone to connect, the service must listen on <strong>all interfaces</strong> (<code>0.0.0.0</code>) and the firewall must allow the port.</p><h2 id="set-ollama-host" tabindex="-1">Set <code>OLLAMA_HOST</code> <a class="header-anchor" href="#set-ollama-host" aria-label="Permalink to &quot;Set `OLLAMA_HOST`&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Start menu → search “environment variables” → “Edit the system environment variables” → “Environment Variables”.</li><li>Under User or System variables, create:</li></ol><table tabindex="0"><thead><tr><th>Name</th><th>Value</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>Save, then <strong>fully quit and reopen</strong> Ollama (exit from the tray, then start again).</li></ol><p>Or temporarily in PowerShell (current session only):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># then restart the Ollama app or service</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Temporary (current session):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>Then quit and reopen the Ollama app. If it resets after reboot, write it into shell config or a LaunchAgent; or:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>and ensure Ollama starts in that environment. Most reliable: <strong>set the env var, then restart Ollama</strong>.</p><h2 id="firewall-port-11434" tabindex="-1">Firewall port 11434 <a class="header-anchor" href="#firewall-port-11434" aria-label="Permalink to &quot;Firewall port 11434&quot;">​</a></h2><ul><li><strong>Windows</strong>: Settings → Privacy &amp; security → Windows Security → Firewall → allow an app; or create an inbound rule for TCP <code>11434</code>.</li><li><strong>macOS</strong>: System Settings → Network → Firewall; allow Ollama on first access, or open the port.</li></ul><h2 id="verify-lan" tabindex="-1">Verify LAN <a class="header-anchor" href="#verify-lan" aria-label="Permalink to &quot;Verify LAN&quot;">​</a></h2><ol><li>Find the PC IP (see <a href="/ultra_guides/en/quickstart#step-4-find-the-pc-lan-ip">Quickstart Step 4</a>).</li><li>From <strong>another device on the same Wi‑Fi</strong>, open:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>Any open / Ollama-like response means LAN works.</p><h2 id="address-for-minitavern" tabindex="-1">Address for MiniTavern <a class="header-anchor" href="#address-for-minitavern" aria-label="Permalink to &quot;Address for MiniTavern&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>Notes:</p><ul><li>Use the LAN IP — <strong>not</strong> <code>localhost</code></li><li>Prefer the <code>/v1</code> suffix (OpenAI-compatible path)</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a></p>',27)])])}const m=e(l,[["render",n]]);export{u as __pageData,m as default};
